-- id=48  زينب بنت خزيمة (أم المساكين)
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 48;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'زينب بنت خزيمة بن الحارث بن عبد الله بن عمرو بن عبد مناف بن هلال بن عامر بن صعصعة الهلالية زوج النبي صلى الله عليه وسلم يقال لها أم المساكين لكثرة إطعامها المساكين وصدقتها عليهم وكانت تحت عبد الله بن جحش فقتل عنها يوم أحد فتزوجها رسول الله صلى الله عليه وسلم وقيل كانت عند الطفيل بن الحارث بن المطلب بن عبد مناف ثم خلف عليها أخوه عبيدة بن الحارث قاله أبو عمر عن على ابن عبد العزيز الجرجاني وقال كانت أخت ميمونة زوج النبي صلى الله عليه وسلم لأمها قال أبو عمر ولم أر ذلك لغيره وتزوجها رسول الله صلى الله عليه وسلم بعد حفصة قال أبو عمر ولم تلبث عند رسول الله صلى الله عليه وسلم إلا يسيرا شهرين أو ثلاثة حتى توفيت وكانت وفاتها في حياته لا خلاف فيه وذكر ابن منده في ترجمتها قول النبي صلى الله عليه وسلم أسرعكن لحوقا بي أطولكن يدا فكان نساء النبي صلى الله عليه وسلم يتذارعن أيتهن أطول يدا فلما توفيت زينب علمن أنها كانت أطولهن يدا في الخير وهذا عندي وهم فإنه صلى الله عليه وسلم قال أسرعكن

لحوقا بي وهذه سبقته إنما أراد أول نسائه تموت بعد وفاته وقد تقدم في زينب بنت جحش وهو بها أشبه لأنها كانت أيضا كثيرة الصدقة من عمل يدها وهي أول نسائه توفيت بعده والله أعلم أخرجها الثلاثة'
WHERE id = 48
  AND content_ar LIKE '(ب د ع) زينب بنت خزي%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 48;

-- id=49  أم سلمة (هند بنت أبي أمية)
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 49;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'أم سلمة بنت أبي أمية بن المغيرة بن عبد الله بن عمر بن مخزوم القرشية المخزومية زوج النبي صلى الله عليه وسلم واسمها هند وكان أبوها يعرف بزاد الركب وكانت قبل النبي صلى الله عليه وسلم عند أبي سلمة بن عبد الأسد المخزومي فولدت له سلمة وعمر ودرة وزينب وتوفي فخلف عليها رسول الله صلى الله عليه وسلم بعده وكانت من المهاجرات إلى الحبشة وإلى المدينة أخبرنا أبو جعفر بإسناده عن يونس عن ابن إسحاق قال حدثني والدي إسحاق بن يسار عن سلمة بن عبد الله بن عمر بن أبي مسلمة عن جدته أم سلمة قالت لما أجمع أبو سلمة الخروج إلى المدينة رحل بعيرا له وحملني وحمل معي ابني سلمة ثم خرج يقود بعيره فلما رآه رجال بني المغيرة بن عبد الله بن عمر بن مخزوم قاموا إليه فقالوا هذه نفسك غلبتنا عليها أرأيت صاحبتنا هذه علام تترك تسير بها في البلاد ونزعوا خطام البعير من يده وأخذوني وغضبت عند ذلك بنو عبد الأسد وأهووا إلى سلمة وقالوا والله لا نترك ابننا عندها إذا نزعتموها من صاحبنا فتجاذبوا ابني سلمة حتى خلعوا يده وانطلق به عبد الأسد رهط أبي سلمة وحبسني بنوا المغيرة عندهم وانطلق زوجي أبو سلمة حتى لحق بالمدينة ففرق بيني وبين زوجي وبين ابني قالت فكنت أخرج كل غداة فأجلس بالأبطح فما أزال أبكي حتي أمسي سنة أو قريبها حتى مر بي رجل من بني عمي من بني المغيرة فرأى ما بي فرحمني فقال لبني المغيرة ألا تخرجون من هذه المسكينة فرقتم بينها وبين زوجها وبين ابنها فقالوا لي الحقي بزوجك إن شئت ورد علي بنو عبد الأسد عند ذلك ابني فرحلت بعيري ووضعت ابني في حجري ثم خرجت أريد زوجي بالمدينة وما معي أحد من خلق الله فقلت أتبلغ بمن لقيت حتى أقدم على زوجي حتى إذا كنت بالتنعيم لقيت عثمان بن طلحة بن أبي طلحة أخا بني عبد الدار فقال أين يا ابنت أبي أمية قلت أريد زوجي بالمدينة فقال هل معك أحد فقلت لا والله إلا الله وابني هذا فقال والله ما لك من منزل فأخذ بخطام البعير فانطلق معي

يقودني فوالله ما صحبت رجلا من العرب أراه كان أكرم منه إذا بلغ المنزل أناخ بي ثم تنحى إلى شجرة فاضطجع تحتها فإذا دنا الرواح قام إلى بعيري فقدمه فرحله ثم استأخر عني وقال اركبي فإذا ركبت واستويت على بعيري أتى فأخذ بخطامه فقادني حتى ننزل فلم يزل يصنع ذلك حتى قدم بي إلى المدينة فلما نظر إلى قرية بني عمرو بن عوف بقباء قال زوجك في هذه القرية وكان أبو سلمة نازلا بها فدخلتها على بركة الله تعالى ثم انصرف راجعا إلى مكة وكانت تقول ما أعلم أهل بيت أصابهم في الإسلام ما أصاب آل أبي سلمة وما رأيت صاحبا قط كان أكرم من عثمان بن طلحة وقيل إنها أول ظعينة هاجرت إلى المدينة والله أعلم وتزوجها رسول الله صلى الله عليه وسلم بعد أبي سلمة أخبرنا يعيش بن صدقة الفقيه بإسناده عن أحمد بن شعيب أخبرنا محمد ابن إسماعيل بن إبراهيم أخبرنا يزيد عن حماد بن سلمة عن ثابت البناني حدثني ابن عمر بن أبي سلمة عن أبيه عن أم سلمة قالت لما انقضت عدتها بعث إليها أبو بكر يخطبها عليه فلم تزوجه فبعث إليها رسول الله صلى الله عليه وسلم عمر بن الخطاب يخطبها عليه فقلت أخبر رسول الله صلى الله عليه وسلم أني امرأة غيرى وأني امرأة مصبية وليس أحد من أوليائي شاهد فأتى رسول الله صلى الله عليه وسلم فذكر ذلك له فقال ارجع إليها فقل لها أما قولك إني امرأة غيرى فسأدعو الله فيذهب غيرتك وأما قولك إني امرأة مصبية فستكفين صبيانك وأما قولك ليس أحد من أوليائي شاهد فليس أحد من أوليائك شاهد ولا غائب يكره ذلك فقالت لابنها عمر قم فزوج رسول الله صلى الله عليه وسلم فزوجه مختصرا أخبرنا أرسلان بن يغان أبو محمد الصوفي أخبرنا أبو الفضل بن طاهر بن سعيد بن أبي سعيد الميهني الصوفي أخبرنا أبو بكر بن أحمد بن علي بن خلف أخبرنا الحاكم أبو عبد الله محمد بن عبد الله أخبرنا أبو العباس محمد بن يعقوب الأصم أخبرنا الحسن بن مكرم أخبرنا عثمان بن عمر أخبرنا عبد الرحمن بن عبد الله بن دينار عن شريك بن أبي نمر عن عطاء بن يسار عن أم سلمة قالت في بيتي نزلت إنما يريد الله ليذهب عنكم الرجس أهل البيت قالت فأرسل رسول الله صلى الله عليه وسلم إلى فاطمة وعلي والحسن والحسين فقال هؤلاء أهل بيتي قالت فقلت يا رسول الله أنا من أهل البيت قال بلى إن شاء الله أخرجها الثلاثة'
WHERE id = 49
  AND content_ar LIKE '(ب د ع) أم سلمة بنت %'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 49;

-- id=50  زينب بنت جحش
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 50;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'زينب بنت جحش زوج النبي صلى الله عليه وسلم أخت عبد الله بن جحش وهي أسدية من أسد بن خزيمة وأمها أميمة بنت عبد المطلب عمة النبي صلى الله عليه وسلم وقد تقدم نسبها عند ذكر أخيها وتكنى أم الحكم وكانت قديمة الإسلام ومن المهاجرات وكانت قد تزوجها زيد بن حارثة مولى النبي صلى الله عليه وسلم تزوجها ليعلمها كتاب الله وسنة رسوله ثم إن الله تعالى زوجها النبي صلى الله عليه وسلم من السماء وأنزل الله تعالى وإذ تقول للذي أنعم الله عليه وأنعمت عليه أمسك عليك زوجك واتق الله وتخفي في نفسك ما الله مبديه وتخشى الناس والله أحق أن تخشاه فلما قضى زيد منها وطرا زوجناكها الآية فتزوجها رسول الله صلى الله عليه وسلم سنة ثلاث من الهجرة قاله أبو عبيدة وقال قتادة سنة خمس وقال ابن إسحاق تزوجها
رسول الله صلى الله عليه وسلم بعد أم سلمة أخبرنا عبد الوهاب بن هبة الله أخبرنا أبو غالب بن البناء أخبرنا أبو محمد الجوهري أخبرنا أبو بكر القطيعي أخبرنا محمد ابن يونس أخبرنا حبان بن هلال أخبرنا سليمان بن المغيرة عن ثابت عن أنس قال لما انقضت عدة زينب بنت جحش قال رسول الله صلى الله عليه وسلم لزيد بن حارثة اذهب فاذكرني لها قال زيد فلما قال لي رسول الله صلى الله عليه وسلم ذلك عظمت في عيني فذهبت إليها فجعلت ظهري إلى الباب فقلت يا زينب بعث بي رسول الله صلى الله عليه وسلم يذكرك فقالت ما كنت لأحدث شيئا حتى أوامر ربي عز وجل فقامت إلى مسجدها وأنزل الله هذه الآية فلما قضى زيد منها وطرا زوجناكها فجعل رسول الله صلى الله عليه وسلم يدخل عليها بغير إذن أخبرنا أبو محمد عبد الله بن علي بن سويدة بإسناده عن علي بن أحمد قال أخبرنا أبو عبد الرحمن محمد بن عبد العزيز الفقيه حدثنا محمد بن الفضل بن محمد السلمي أخبرنا أبي أخبرنا أبو أحمد محمد بن عبد الوهاب أخبرنا الحسين بن الوليد عن عيسى بن طهمان عن أنس بن مالك قال كانت زينب بنت جحش تفخر على نساء النبي صلى الله عليه وسلم وتقول زوجني الله من السماء وأولم عليها رسول الله صلى الله عليه وسلم بخبز ولحم وكانت زينب كثيرة الخير والصدقة ولما دخلت على رسول الله صلى الله عليه وسلم كان اسمها برة فسماها زينب وتكلم المنافقون في ذلك وقالوا إن محمدا يحرم نكاح نساء الأولاد وقد تزوج امرأة ابنه زيد لأنه كان يقال له زيد ابن محمد قال الله تعالى ما كان محمد أبا أحد من رجالكم وقال ادعوهم لآبائهم هو أقسط عند الله فكان يدعى زيد بن حارثة وهجرها رسول الله صلى الله عليه وسلم وغضب عليها لما قالت لصفية بنت حي تلك اليهودية فهجرها ذا الحجة والمحرم وبعض صفر وعاد إلى ما كان عليه وقيل إن التي قالت لها ذلك حفصة وقالت عائشة لم يكن أحد من نساء النبي صلى الله عليه وسلم تساميني في حسن المنزلة عنده إلا زينب بنت جحش وكانت تفخر على نساء النبي صلى الله عليه وسلم وتقول إن آباءكن أنكحكن وإن الله أنكحني إياه وبسببها نزل الحجاب وكانت امرأة صناع اليد تعمل بيدها وتتصدق به في سبيل الله أخبرنا أبو الفضل بن أبي الحسن الفقيه بإسناده إلى أبي يعلى حدثنا هارون بن عبد الله عن ابن أبي فديك أخبرنا ابن أبي ذئب حدثني صالح مولى التوامة عن أبي هريرة أن رسول الله صلى الله عليه وسلم قال للنساء عام 
حجة الوداع هذه ثم ظهور الحصر قال فكن كلهن يحججن إلا سودة وزينب بنت جحش فإنهما كانتا يقولان والله لا تحركنا دابة بعد إذ سمعنا من رسول الله صلى الله عليه وسلم أخبرنا يحيى وأبو ياسر بإسنادهما عن مسلم قال حدثنا محمود بن غيلان حدثنا الفضل بن موسى الشيباني أخبرنا طلحة بن يحيى بن طلحة عن عائشة بنت طلحة عن عائشة أم المؤمنين قالت قال رسول الله صلى الله عليه وسلم أسرعكن لحوقا بي أطولكن يدا قالت فكنا نتطاول أيهن أطول يدا قالت فكانت زينب أطولنا يدا لأنها كانت تعمل بيدها وتتصدق وقالت عائشة ما رأيت امرأة قط خيرا في الدين من زينب وأتقى لله وأصدق حديثا وأوصل للرحم وأعظم أمانة وصدقة وروى شهر بن حوشب عن عبد الله بن شداد أن رسول الله صلى الله عليه وسلم قال لعمر بن الخطاب أن زينب بنت جحش لأواهة فقال رجل يا رسول الله ما الأواه قال المتخشع المتضرع وكانت أول نساء رسول الله صلى الله عليه وسلم لحوقا به كما أخبر رسول الله صلى الله عليه وسلم وتوفيت سنة عشرين أرسل إليها عمر بن الخطاب اثني عشر ألف درهم كما فرض لنساء النبي صلى الله عليه وسلم فأخذتها وفرقتها في ذوي قرابتها وأيتامها ثم قالت اللهم لا يدركني عطاء لعمر بن الخطاب بعد هذا فماتت وصلى عليها عمر بن الخطاب ودخل قبرها أسامة بن زيد ومحمد بن عبد الله بن جحش وعبد الله بن أبي أحمد بن جحش قيل هي أول امرأة صنع لها النعش ودفنت بالبقيع أخرجها الثلاثة'
WHERE id = 50
  AND content_ar LIKE '(ب د ع) زينب بنت جحش%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 50;

